const rows = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

const normalizeDate = value => {
  if (!value) return null;

  // Google Sheets may return dates as numbers.
  if (typeof value === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(
      excelEpoch.getTime() + value * 86400000
    );
    date.setHours(0, 0, 0, 0);
    return date;
  }

  const date = new Date(`${String(value).trim()}T00:00:00`);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

const eligibleLeads = rows.filter(item => {
  const row = item.json;

  const validOutreachStatuses = [
    'Sent',
    'Contacted',
    'Follow-up due',
  ];

  const hasValidOutreachStatus = validOutreachStatuses.includes(
    String(row.outreach_status || '').trim()
  );

  const doNotContact =
    row.do_not_contact === true ||
    String(row.do_not_contact || '')
      .trim()
      .toLowerCase() === 'true';

  const nextActionDate =
    normalizeDate(row.next_action_date);

  const hasEmail =
    String(row.primary_email || '').trim() !== '';

  const followUpCount =
    Number(row.follow_up_count || 0);

  const hasReply =
    String(row.last_reply_message_id || '').trim() !== '' ||
    String(row.last_reply_date || '').trim() !== '';

  return (
    hasValidOutreachStatus &&
    !doNotContact &&
    !hasReply &&
    hasEmail &&
    nextActionDate &&
    nextActionDate <= today &&
    followUpCount < 2
  );
});

return eligibleLeads
  .sort((a, b) => {
    const dateA =
      normalizeDate(a.json.next_action_date)?.getTime() || 0;

    const dateB =
      normalizeDate(b.json.next_action_date)?.getTime() || 0;

    return dateA - dateB;
  })
  .slice(0, 20);

const dueLeads =
  $('Select Leads Due for Follow-up').all();

const outreachDrafts = $input.all();

const normalized = value =>
  String(value || '').trim().toLowerCase();

const pendingStatuses = [
  'draft ready for review',
  'approved to draft',
  'pending review',
  'gmail draft created',
  'scheduled',
  'scheduled for send',
];

const results = [];

for (const leadItem of dueLeads) {
  const lead = leadItem.json;

  const leadDrafts = outreachDrafts
    .map(item => item.json)
    .filter(draft =>
      normalized(draft.lead_id) ===
      normalized(lead.lead_id)
    );

  const hasPendingFollowUp =
    leadDrafts.some(draft => {
      const campaignId =
        normalized(draft.campaign_id);

      const draftStatus =
        normalized(draft.draft_status);

      return (
        campaignId.startsWith(
          'example_outreach_followup'
        ) &&
        pendingStatuses.includes(draftStatus)
      );
    });

  if (hasPendingFollowUp) {
    continue;
  }

  const sentDrafts = leadDrafts.filter(
    draft =>
      normalized(draft.draft_status) ===
      'sent'
  );

  if (sentDrafts.length === 0) {
    continue;
  }

  sentDrafts.sort((a, b) => {
    const dateA = new Date(
      a.sent_at || a.created_at || 0
    ).getTime();

    const dateB = new Date(
      b.sent_at || b.created_at || 0
    ).getTime();

    return dateB - dateA;
  });

  const originalEmail = sentDrafts[0];

  results.push({
    json: {
      ...lead,

      original_draft_id:
        originalEmail.draft_id || '',

      original_subject:
        originalEmail.subject || '',

      original_body:
        originalEmail.body || '',

      original_sent_at:
        originalEmail.sent_at || '',

      original_gmail_draft_id:
        originalEmail.gmail_draft_id || '',

      follow_up_number:
        Number(lead.follow_up_count || 0) + 1,
    },
  });
}

return results.slice(0, 5);

