const lead =
  $('Match Lead to Sent Email').item.json;

const output = $json.output || [];

let rawText = '';

for (const message of output) {
  for (const content of message.content || []) {
    if (
      content.type === 'output_text' &&
      content.text
    ) {
      rawText = content.text;
      break;
    }
  }

  if (rawText) {
    break;
  }
}

if (!rawText) {
  throw new Error(
    'The model returned no follow-up content.'
  );
}

let draft;

try {
  draft = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    'The model response does not contain valid JSON.'
  );
}

const cleanBody = String(draft.body || '')
  .split('\n')
  .map(line => {
    if (
      String(line)
        .toLowerCase()
        .includes('example.com')
    ) {
      return 'https://example.com/';
    }

    return line;
  })
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const subject =
  String(draft.subject || '').trim();

if (!subject || !cleanBody) {
  throw new Error(
    'The follow-up lacks a subject or body.'
  );
}

const timestamp =
  new Date().toISOString();

return {
  json: {
    ...lead,

    follow_up_draft_id:
      `followup_${lead.lead_id}_${Date.now()}`,

    recipient_email:
      lead.primary_email,

    follow_up_subject:
      subject,

    follow_up_body:
      cleanBody,

    follow_up_number:
      Number(lead.follow_up_number || 1),

    follow_up_status:
      'Draft ready for review',

    generated_at:
      timestamp,
    link_format_valid:
      !cleanBody.includes('[https://') &&
      !cleanBody.includes(']('),
  },
};
